def check_braces(format_str):
    '''Check if braces are balanced and properly formed.'''
    i = 0
    while i < len(format_str):
        if format_str[i] == '{':
            # Check if it's {{ (escaped)
            if i + 1 < len(format_str) and format_str[i+1] == '{':
                i += 2  # skip {{
            else:
                # Look for matching }
                j = format_str.find('}', i+1)
                if j == -1:
                    return False, f'Unmatched {{ at position {i}'
                # Check for nested { before finding }
                nested = format_str.find('{', i+1)
                if nested != -1 and nested < j:
                    return False, f'Nested {{ found before matching }}'
                i = j + 1
        elif format_str[i] == '}':
            # Check if it's }} (escaped)
            if i + 1 < len(format_str) and format_str[i+1] == '}':
                i += 2  # skip }}
            else:
                return False, f'Unmatched }} at position {i}'
        else:
            i += 1
    return True, 'OK'

test_cases = [
    ('{abc}}', True),   # field {abc} followed by escaped }
    ('{{abc}', False),  # escaped {{, then abc} with unmatched }
    ('{{{', False),     # escaped {{, then orphan {
    ('{}}}', False),    # field {}, then orphan }
    ('}}{', False),     # escaped }}, then orphan {
]

for tc, expected in test_cases:
    result, msg = check_braces(tc)
    status = 'PASS' if result == expected else 'FAIL'
    print(f'{status}: {repr(tc):20} -> {result} (expected {expected})')
